using FamilyVeda.Application.Common;
using FamilyVeda.Application.Portal;
using FamilyVeda.Domain.Clinical;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Domain.Portal;
using FamilyVeda.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
using FamilyVeda.Infrastructure.Clinical;
using FamilyVeda.Infrastructure.Families;

namespace FamilyVeda.Infrastructure.Portal;

public sealed class AppointmentService(AppDbContext dbContext, ICurrentUser currentUser) : IAppointmentService
{
    public async Task<AppointmentDto> BookAsync(CreateAppointmentRequest request, CancellationToken cancellationToken)
    {
        var member = await dbContext.Members.SingleOrDefaultAsync(x => x.Id == request.MemberId, cancellationToken) ?? throw new NotFoundException();
        var isSelf = member.UserId == currentUser.UserId;
        var isMinor = member.DateOfBirth.AddYears(18) > DateOnly.FromDateTime(DateTime.UtcNow);
        var isHead = await dbContext.Families.Where(x => x.Id == member.FamilyId).AnyAsync(FamilyAccess.HeadedBy(currentUser.UserId), cancellationToken);
        var allowed = isSelf || (isHead && isMinor);
        if (!allowed)
        {
            throw new NotFoundException();
        }

        if (string.IsNullOrWhiteSpace(request.Reason) || request.Reason.Trim().Length > 200)
        {
            throw new Application.Common.ValidationException(new Dictionary<string, string[]> { ["reason"] = ["Reason is required and cannot exceed 200 characters."] });
        }

        if (request.StartsAt <= DateTimeOffset.UtcNow)
        {
            throw new Application.Common.ValidationException(new Dictionary<string, string[]> { ["startsAt"] = ["Appointment time must be in the future."] });
        }

        var duration = request.DurationMinutes ?? 30;
        if (duration is < 15 or > 120)
        {
            throw new Application.Common.ValidationException(new Dictionary<string, string[]> { ["durationMinutes"] = ["Duration must be between 15 and 120 minutes."] });
        }

        var assignment = await dbContext.FamilyDoctorAssignments.AsNoTracking()
            .FirstOrDefaultAsync(x => x.FamilyId == member.FamilyId && x.IsPrimary && x.EndedAt == null, cancellationToken)
            ?? throw new ConflictException("This family does not have a primary doctor yet.");

        var endsAt = request.StartsAt.AddMinutes(duration);
        var overlapping = await dbContext.Appointments.AnyAsync(x =>
            x.DoctorId == assignment.DoctorId &&
            (x.Status == AppointmentStatus.Requested || x.Status == AppointmentStatus.Confirmed) &&
            x.StartsAt < endsAt &&
            request.StartsAt < x.StartsAt.AddMinutes(x.DurationMinutes), cancellationToken);
        if (overlapping)
        {
            throw new ConflictException("The doctor already has an appointment overlapping this time.");
        }
        await RequireFitsScheduleAsync(assignment.DoctorId, request.StartsAt, duration, cancellationToken);

        var appointment = new Appointment
        {
            MemberId = member.Id,
            DoctorId = assignment.DoctorId,
            BookedByUserId = currentUser.UserId,
            StartsAt = request.StartsAt,
            DurationMinutes = duration,
            Reason = request.Reason.Trim()
        };
        dbContext.Appointments.Add(appointment);
        AddAudit("APPOINTMENT_REQUESTED", appointment.Id);
        var doctorUserId = await dbContext.Doctors.Where(x => x.Id == assignment.DoctorId).Select(x => x.UserId).SingleAsync(cancellationToken);
        AddNotification(doctorUserId, "APPOINTMENT_REQUESTED", "New appointment request", "A new appointment has been requested.", "/doctor/appointments");
        await dbContext.SaveChangesAsync(cancellationToken);
        return await MapAsync(appointment, cancellationToken);
    }

    public async Task<IReadOnlyList<AppointmentDto>> GetMineAsync(CancellationToken cancellationToken)
    {
        var myMemberIds = await dbContext.Members.Where(x => x.UserId == currentUser.UserId).Select(x => x.Id).ToListAsync(cancellationToken);
        var head = await dbContext.Families.FirstOrDefaultAsync(FamilyAccess.HeadedBy(currentUser.UserId), cancellationToken);
        var memberIds = new List<Guid>(myMemberIds);
        if (head is not null)
        {
            var adultCutoff = DateOnly.FromDateTime(DateTime.UtcNow).AddYears(-18);
            var minorIds = await dbContext.Members.Where(x => x.FamilyId == head.Id && x.DateOfBirth > adultCutoff).Select(x => x.Id).ToListAsync(cancellationToken);
            memberIds.AddRange(minorIds);
        }

        return await ProjectAsync(dbContext.Appointments.AsNoTracking()
            .Where(x => memberIds.Contains(x.MemberId))
            .OrderByDescending(x => x.StartsAt), cancellationToken);
    }

    public async Task<AppointmentDto> CancelAsync(Guid id, CancellationToken cancellationToken)
    {
        var appointment = await dbContext.Appointments.SingleOrDefaultAsync(x => x.Id == id, cancellationToken) ?? throw new NotFoundException();
        var member = await dbContext.Members.SingleAsync(x => x.Id == appointment.MemberId, cancellationToken);
        var allowed = appointment.BookedByUserId == currentUser.UserId || member.UserId == currentUser.UserId;
        if (!allowed)
        {
            // A doctor-booked follow-up for a minor has no family booker, so the family head may cancel it.
            var isMinor = member.DateOfBirth.AddYears(18) > DateOnly.FromDateTime(DateTime.UtcNow);
            allowed = isMinor && await dbContext.Families.Where(x => x.Id == member.FamilyId).AnyAsync(FamilyAccess.HeadedBy(currentUser.UserId), cancellationToken);
        }
        if (!allowed)
        {
            throw new NotFoundException();
        }
        if (appointment.Status is not (AppointmentStatus.Requested or AppointmentStatus.Confirmed))
        {
            throw new ConflictException($"Appointment cannot be cancelled from status {appointment.Status}.");
        }

        appointment.Status = AppointmentStatus.Cancelled;
        await RevokeVisitGrantsAsync(appointment.Id, cancellationToken);
        AddAudit("APPOINTMENT_STATUS_CHANGED", appointment.Id);
        await dbContext.SaveChangesAsync(cancellationToken);
        return await MapAsync(appointment, cancellationToken);
    }

    public async Task<IReadOnlyList<AppointmentDto>> GetForDoctorAsync(DateTimeOffset? from, DateTimeOffset? to, CancellationToken cancellationToken)
    {
        var doctor = await RequireDoctorAsync(cancellationToken);
        var query = dbContext.Appointments.AsNoTracking().Where(x => x.DoctorId == doctor.Id);
        if (from is not null) query = query.Where(x => x.StartsAt >= from);
        if (to is not null) query = query.Where(x => x.StartsAt <= to);
        return await ProjectAsync(query.OrderBy(x => x.StartsAt), cancellationToken);
    }

    public Task<AppointmentDto> ConfirmAsync(Guid id, AppointmentActionRequest request, CancellationToken cancellationToken) =>
        TransitionAsync(id, AppointmentStatus.Requested, AppointmentStatus.Confirmed, request, cancellationToken);

    public Task<AppointmentDto> CompleteAsync(Guid id, AppointmentActionRequest request, CancellationToken cancellationToken) =>
        TransitionAsync(id, AppointmentStatus.Confirmed, AppointmentStatus.Completed, request, cancellationToken);

    public Task<AppointmentDto> NoShowAsync(Guid id, AppointmentActionRequest request, CancellationToken cancellationToken) =>
        TransitionAsync(id, AppointmentStatus.Confirmed, AppointmentStatus.NoShow, request, cancellationToken);

    public async Task<AppointmentDto> DoctorCancelAsync(Guid id, AppointmentActionRequest request, CancellationToken cancellationToken)
    {
        var doctor = await RequireDoctorAsync(cancellationToken);
        var appointment = await dbContext.Appointments.SingleOrDefaultAsync(x => x.Id == id && x.DoctorId == doctor.Id, cancellationToken) ?? throw new NotFoundException();
        if (appointment.Status is not (AppointmentStatus.Requested or AppointmentStatus.Confirmed))
        {
            throw new ConflictException($"Appointment cannot be cancelled from status {appointment.Status}.");
        }
        appointment.Status = AppointmentStatus.Cancelled;
        if (!string.IsNullOrWhiteSpace(request.Note)) appointment.DoctorNote = request.Note.Trim();
        await RevokeVisitGrantsAsync(appointment.Id, cancellationToken);
        AddAudit("APPOINTMENT_STATUS_CHANGED", appointment.Id);
        await dbContext.SaveChangesAsync(cancellationToken);
        return await MapAsync(appointment, cancellationToken);
    }

    private async Task<AppointmentDto> TransitionAsync(Guid id, AppointmentStatus from, AppointmentStatus to, AppointmentActionRequest request, CancellationToken cancellationToken)
    {
        var doctor = await RequireDoctorAsync(cancellationToken);
        var appointment = await dbContext.Appointments.SingleOrDefaultAsync(x => x.Id == id && x.DoctorId == doctor.Id, cancellationToken) ?? throw new NotFoundException();
        if (appointment.Status != from)
        {
            throw new ConflictException($"Appointment cannot transition from {appointment.Status} to {to}.");
        }
        // Confirming after the start would open a visit grant for a visit nobody confirmed in advance.
        if (to == AppointmentStatus.Confirmed && appointment.StartsAt <= DateTimeOffset.UtcNow)
        {
            throw new ConflictException("This appointment has already started. Reschedule it or cancel it instead.");
        }
        appointment.Status = to;
        if (!string.IsNullOrWhiteSpace(request.Note)) appointment.DoctorNote = request.Note.Trim();
        if (to == AppointmentStatus.Confirmed) IssueVisitGrant(appointment);
        if (to == AppointmentStatus.NoShow) await RevokeVisitGrantsAsync(appointment.Id, cancellationToken);
        AddAudit("APPOINTMENT_STATUS_CHANGED", appointment.Id);
        await dbContext.SaveChangesAsync(cancellationToken);
        return await MapAsync(appointment, cancellationToken);
    }

    /// <summary>Doctor moves a requested or confirmed appointment. The family is notified; a confirmed visit's grant follows the new time.</summary>
    public async Task<AppointmentDto> RescheduleAsync(Guid id, RescheduleAppointmentRequest request, CancellationToken cancellationToken)
    {
        var doctor = await RequireDoctorAsync(cancellationToken);
        var appointment = await dbContext.Appointments.SingleOrDefaultAsync(x => x.Id == id && x.DoctorId == doctor.Id, cancellationToken) ?? throw new NotFoundException();
        if (appointment.Status is not (AppointmentStatus.Requested or AppointmentStatus.Confirmed))
        {
            throw new ConflictException($"Appointment cannot be rescheduled from status {appointment.Status}.");
        }
        if (request.StartsAt <= DateTimeOffset.UtcNow)
        {
            throw new Application.Common.ValidationException(new Dictionary<string, string[]> { ["startsAt"] = ["The new time must be in the future."] });
        }
        var endsAt = request.StartsAt.AddMinutes(appointment.DurationMinutes);
        var overlapping = await dbContext.Appointments.AnyAsync(x =>
            x.Id != appointment.Id && x.DoctorId == doctor.Id &&
            (x.Status == AppointmentStatus.Requested || x.Status == AppointmentStatus.Confirmed) &&
            x.StartsAt < endsAt && request.StartsAt < x.StartsAt.AddMinutes(x.DurationMinutes), cancellationToken);
        if (overlapping) throw new ConflictException("You already have an appointment overlapping this time.");
        await RequireFitsScheduleAsync(doctor.Id, request.StartsAt, appointment.DurationMinutes, cancellationToken);

        appointment.RescheduledFromStartsAt = appointment.StartsAt;
        appointment.StartsAt = request.StartsAt;
        appointment.UpdatedAt = DateTimeOffset.UtcNow;
        if (!string.IsNullOrWhiteSpace(request.Note)) appointment.DoctorNote = request.Note.Trim();
        // A follow-up the doctor booked carries no visit grant: the patient never agreed to record access.
        var doctorBooked = appointment.BookedByUserId == doctor.UserId;
        if (appointment.Status == AppointmentStatus.Confirmed && !doctorBooked)
        {
            await RevokeVisitGrantsAsync(appointment.Id, cancellationToken);
            IssueVisitGrant(appointment);
        }
        AddAudit("APPOINTMENT_RESCHEDULED", appointment.Id);
        var recipients = doctorBooked
            ? await EmergencyCaseAccess.PatientRecipientsAsync(dbContext, appointment.MemberId, cancellationToken)
            : [appointment.BookedByUserId];
        foreach (var userId in recipients)
        {
            AddNotification(userId, "APPOINTMENT_RESCHEDULED", "Appointment moved",
                "Your doctor moved an appointment to a new time. Open Appointments to see it.", "/appointments");
        }
        await dbContext.SaveChangesAsync(cancellationToken);
        return await MapAsync(appointment, cancellationToken);
    }

    /// <summary>
    /// A doctor books a follow-up for the patient of an emergency referral they acknowledged. It is
    /// confirmed at once and the patient may cancel it. No visit grant is issued, so the booking gives
    /// the doctor no access to the patient's records (agent/DECISIONS.md 2026-10-05b).
    /// </summary>
    public async Task<AppointmentDto> BookFollowUpAsync(Guid caseId, FollowUpAppointmentRequest request, CancellationToken cancellationToken)
    {
        var access = await EmergencyCaseAccess.RequireAsync(dbContext, currentUser, caseId, cancellationToken);
        var reason = string.IsNullOrWhiteSpace(request.Reason) ? "Follow-up after urgent care referral" : request.Reason.Trim();
        if (reason.Length > 200)
        {
            throw new Application.Common.ValidationException(new Dictionary<string, string[]> { ["reason"] = ["Reason cannot exceed 200 characters."] });
        }
        if (request.StartsAt <= DateTimeOffset.UtcNow)
        {
            throw new Application.Common.ValidationException(new Dictionary<string, string[]> { ["startsAt"] = ["Appointment time must be in the future."] });
        }
        var duration = request.DurationMinutes ?? 30;
        if (duration is < 15 or > 120)
        {
            throw new Application.Common.ValidationException(new Dictionary<string, string[]> { ["durationMinutes"] = ["Duration must be between 15 and 120 minutes."] });
        }
        var doctorId = access.Doctor.Id;
        var memberId = access.Case.MemberId;
        var hasOpenFollowUp = await dbContext.Appointments.AnyAsync(x =>
            x.DoctorId == doctorId && x.MemberId == memberId && x.BookedByUserId == currentUser.UserId &&
            x.Status == AppointmentStatus.Confirmed && x.StartsAt > DateTimeOffset.UtcNow, cancellationToken);
        if (hasOpenFollowUp) throw new ConflictException("You already booked a follow-up for this patient.");
        var endsAt = request.StartsAt.AddMinutes(duration);
        var overlapping = await dbContext.Appointments.AnyAsync(x =>
            x.DoctorId == doctorId &&
            (x.Status == AppointmentStatus.Requested || x.Status == AppointmentStatus.Confirmed) &&
            x.StartsAt < endsAt && request.StartsAt < x.StartsAt.AddMinutes(x.DurationMinutes), cancellationToken);
        if (overlapping) throw new ConflictException("You already have an appointment overlapping this time.");
        await RequireFitsScheduleAsync(doctorId, request.StartsAt, duration, cancellationToken);

        var appointment = new Appointment
        {
            MemberId = memberId,
            DoctorId = doctorId,
            BookedByUserId = currentUser.UserId,
            StartsAt = request.StartsAt,
            DurationMinutes = duration,
            Reason = reason,
            Status = AppointmentStatus.Confirmed
        };
        dbContext.Appointments.Add(appointment);
        dbContext.AuditLogs.Add(new AuditLog
        {
            ActorUserId = currentUser.UserId,
            SubjectMemberId = memberId,
            EventType = "FOLLOW_UP_APPOINTMENT_BOOKED",
            ResourceType = "Appointment",
            ResourceId = appointment.Id,
            Outcome = "SUCCESS",
            MetadataJson = "{}"
        });
        foreach (var userId in await EmergencyCaseAccess.PatientRecipientsAsync(dbContext, memberId, cancellationToken))
        {
            AddNotification(userId, "APPOINTMENT_CONFIRMED", "A doctor booked a follow-up appointment",
                "A doctor who saw your urgent care referral booked a follow-up appointment for you. Open Appointments to see the time or cancel it. This does not replace urgent in-person care.",
                "/appointments");
        }
        await dbContext.SaveChangesAsync(cancellationToken);
        return await MapAsync(appointment, cancellationToken);
    }

    /// <summary>DECISIONS 2026-09-29h: clinical access for this member from 24 h before the start to 24 h after the end.</summary>
    private void IssueVisitGrant(Appointment appointment)
    {
        dbContext.VisitAccessGrants.Add(new VisitAccessGrant
        {
            AppointmentId = appointment.Id,
            DoctorId = appointment.DoctorId,
            MemberId = appointment.MemberId,
            StartsAt = appointment.StartsAt - VisitAccessGrant.Margin,
            ExpiresAt = appointment.StartsAt.AddMinutes(appointment.DurationMinutes) + VisitAccessGrant.Margin
        });
        dbContext.AuditLogs.Add(new AuditLog
        {
            ActorUserId = currentUser.UserId,
            SubjectMemberId = appointment.MemberId,
            EventType = "VISIT_GRANT_ISSUED",
            ResourceType = "Appointment",
            ResourceId = appointment.Id,
            Outcome = "SUCCESS",
            MetadataJson = "{}"
        });
    }

    private async Task RevokeVisitGrantsAsync(Guid appointmentId, CancellationToken cancellationToken)
    {
        var now = DateTimeOffset.UtcNow;
        var grants = await dbContext.VisitAccessGrants.Where(x => x.AppointmentId == appointmentId && x.RevokedAt == null).ToListAsync(cancellationToken);
        foreach (var grant in grants) { grant.RevokedAt = now; grant.UpdatedAt = now; }
    }

    /// <summary>Only enforced once the doctor has set weekly hours, so existing bookings keep working.</summary>
    private async Task RequireFitsScheduleAsync(Guid doctorId, DateTimeOffset startsAt, int durationMinutes, CancellationToken cancellationToken)
    {
        var windows = await dbContext.DoctorAvailability.AsNoTracking().Where(x => x.DoctorId == doctorId)
            .Select(x => new DoctorSchedule.Window(x.DayOfWeek, x.StartTime, x.EndTime)).ToListAsync(cancellationToken);
        var endsAt = startsAt.AddMinutes(durationMinutes);
        var blocked = await dbContext.DoctorUnavailablePeriods.AsNoTracking()
            .Where(x => x.DoctorId == doctorId && x.StartsAt < endsAt && startsAt < x.EndsAt)
            .Select(x => new DoctorSchedule.Busy(x.StartsAt, x.EndsAt)).ToListAsync(cancellationToken);
        if (blocked.Count > 0) throw new ConflictException("The doctor is not available at this time.");
        if (windows.Count > 0 && !DoctorSchedule.Fits(startsAt, durationMinutes, windows, blocked))
        {
            throw new ConflictException("This time is outside the doctor's working hours. Pick one of the free slots.");
        }
    }

    private async Task<Doctor> RequireDoctorAsync(CancellationToken cancellationToken) =>
        await dbContext.Doctors.SingleOrDefaultAsync(x => x.UserId == currentUser.UserId && x.VerificationStatus == Domain.Common.VerificationStatus.Verified, cancellationToken)
            ?? throw new ForbiddenException();

    /// <summary>
    /// One joined query for any number of appointments. Mapping row by row cost three round trips per
    /// appointment, which is what made the calendar slow against a hosted database.
    /// </summary>
    private static async Task<IReadOnlyList<AppointmentDto>> ProjectAsync(IQueryable<Appointment> query, CancellationToken cancellationToken) =>
        await query.Select(x => new AppointmentDto(x.Id, x.MemberId, x.Member!.DisplayName, x.Member.Family!.Name,
            new DoctorSummaryDto(x.DoctorId, x.Doctor!.User != null ? x.Doctor.User.DisplayName : "Unknown",
                x.Doctor.Specialty, x.Doctor.HospitalClinic, x.Doctor.District, x.Doctor.City, x.Doctor.Languages),
            x.StartsAt, x.DurationMinutes, x.Reason, x.Status, x.DoctorNote, x.CreatedAt)).ToListAsync(cancellationToken);

    private async Task<AppointmentDto> MapAsync(Appointment appointment, CancellationToken cancellationToken) =>
        (await ProjectAsync(dbContext.Appointments.AsNoTracking().Where(x => x.Id == appointment.Id), cancellationToken)).Single();

    private void AddAudit(string eventType, Guid resourceId) => dbContext.AuditLogs.Add(new AuditLog
    {
        ActorUserId = currentUser.UserId,
        EventType = eventType,
        ResourceType = "Appointment",
        ResourceId = resourceId,
        Outcome = "SUCCESS",
        MetadataJson = "{}"
    });

    private void AddNotification(Guid userId, string type, string title, string body, string? linkPath) =>
        dbContext.PortalNotifications.Add(new PortalNotification { UserId = userId, Type = type, Title = title, Body = body, LinkPath = linkPath });
}
